function worldObjects(){const out=[];for(let x=2;x<19;x++)for(let y=2;y<19;y++){const r=seeded(x,y,12);if(r>.92&&Math.abs(x-15)>2&&Math.abs(y-15)>2)out.push({x,y,type:'tree'});}
