function render(){const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;ctx.clearRect(0,0,w,h);const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#91a884');sky.addColorStop(.7,'#71875f');sky.addColorStop(1,'#536648');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
