function castSpell(which){const def=classDefs[state.className];if(which==='fire'){const t=state.target;if(!t||!t.alive){toast('Choose a target first.','bad');return;}if(state.mp<12){toast('Not enough mana.','bad');return;}if(distance(state,t)>7){toast('Your target is too far away.','bad');return;}state.mp-=12;const d=Math.round(13+state.stats.mag*1.6+state.level*2+Math.random()*5);t.hp-=d;state.skills.Magic+=.28;spawnFloat(t.x,t.y,`✹ ${d}`,'#ffc079');toast('Ember bolt!','good');if(t.hp<=0)killEnemy(t);updateHud();}
