function update(dt){state.elapsed+=dt;state.attackTimer=Math.max(0,state.attackTimer-dt);state.mp=Math.min(maxMp(),state.mp+dt*.75);for(const f of state.floating)f.life-=dt;state.floating=state.floating.filter(f=>f.life>0);
  if(state.walkTo){const tx=state.walkTo.x-state.x,ty=state.walkTo.y-state.y,d=Math.hypot(tx,ty);if(d<.08){state.x=state.walkTo.x;state.y=state.walkTo.y;state.walkTo=null;}else{const step=Math.min(d,dt*3.8);state.x+=tx/d*step;state.y+=ty/d*step;}}
