function openModal(html){state.modal=true;modal.innerHTML=html;backdrop.classList.remove('hidden');}
function closeModal(){state.modal=false;backdrop.classList.add('hidden');}
function characterModal(first=false){const factions=['Aresden','Elvine'];const classes=['Warrior','Wizard','Battlemage'];openModal(`<button class="modal-close" data-close>×</button><div class="eyebrow">A NEW CHRONICLE</div><h2>${first?'Forge Your Legend':'Character Chronicle'}</h2><p class="modal-lead">Choose your allegiance and calling. Your journey begins in a frontier town.</p><label>CHARACTER NAME</label><input id="charNameInput" maxlength="14" value="${state.name}" placeholder="Name your hero"><label>CHOOSE A NATION</label><div class="faction-choice">${factions.map(f=>`<button class="choice ${state.selectedFaction===f?'active':''}" data-faction="${f}"><strong>${f}</strong><small>${f==='Aresden'?'The western crown · crimson banners':'The eastern realm · blue banners'}</small></button>`).join('')}</div><label>CHOOSE YOUR CLASS</label><div class="class-choice">${classes.map(c=>`<button class="choice ${state.selectedClass===c?'active':''}" data-class="${c}"><strong>${c}</strong><small>${c==='Warrior'?'Steel & valor':c==='Wizard'?'Arcane arts':'Blade & spell'}</small></button>`).join('')}</div><button class="primary-btn" id="beginBtn">${first?'ENTER THE REALM':'SAVE CHANGES'}</button>`);
  modal.querySelectorAll('[data-faction]').forEach(b=>b.onclick=()=>{state.selectedFaction=b.dataset.faction;characterModal(first);});modal.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{state.selectedClass=b.dataset.class;characterModal(first);});modal.querySelector('[data-close]').onclick=()=>first?null:closeModal();modal.querySelector('#beginBtn').onclick=()=>{const name=modal.querySelector('#charNameInput').value.trim();if(!name){toast('Choose a name for your character.','bad');return;}state.name=name;state.faction=state.selectedFaction;state.className=state.selectedClass;state.stats={...classDefs[state.className]};state.hp=classDefs[state.className].hp;state.mp=classDefs[state.className].mp;const weapon=classDefs[state.className].weapon;state.equipment.weapon=weapon;if(!state.inventory.includes(weapon))state.inventory.unshift(weapon);save();updateHud();closeModal();if(first)toast(`Welcome to ${state.faction}, ${state.name}.`,'good');};
}
function equipmentModal(){const items=state.inventory;const cells=Array.from({length:20},(_,i)=>{const item=items[i],info=itemCatalog[item]||{};return `<button class="item-cell" title="${item?`${item} · ${info.rarity||'Common'}${info.damage?` · +${info.damage} damage`:''}`:'Empty slot'}" data-item-index="${i}">${item?`${info.icon||'◇'}<small>${item}</small>${info.rarity==='Rare'?'<i class="quality">✦</i>':''}`:''}</button>`;}).join('');const slot=(key,label)=>`<div class="equip-row"><span>${label}</span><b>${state.equipment[key]||'—'}</b></div>`;openModal(`<button class="modal-close" data-close>×</button><div class="eyebrow">PERSONAL STORES</div><h2>Inventory & Equipment</h2><p class="modal-lead">20 pack slots · Select an item to equip it. Consumables are used from your quick bar.</p><div class="equip-grid">${slot('weapon','Weapon')}${slot('armor','Armor')}${slot('ring','Charm')}${`<div class="equip-row"><span>Health tonics</span><b>${state.potions}</b></div>`}</div><div class="inventory-grid">${cells}</div><p class="modal-lead">${items.length}/20 items · Rare equipment glimmers with ✦</p>`);modal.querySelector('[data-close]').onclick=closeModal;modal.querySelectorAll('[data-item-index]').forEach(b=>b.onclick=()=>{const item=state.inventory[Number(b.dataset.itemIndex)];if(!item)return;const data=itemCatalog[item]||{};if(data.type==='weapon'||data.type==='armor'||data.type==='ring'){const slot=data.type==='weapon'?'weapon':data.type==='armor'?'armor':'ring';const old=state.equipment[slot];state.equipment[slot]=item;state.inventory.splice(Number(b.dataset.itemIndex),1);if(old)state.inventory.push(old);toast(`${item} equipped.`,'good');save();equipmentModal();}else if(item==='Minor health tonic'){toast('Use tonics with the 3 key.');}else toast(`${item} will be useful to the guard.`);});}
function characterSheet(){const s=statsForLevel(),weapon=itemCatalog[state.equipment.weapon]||{};openModal(`<button class="modal-close" data-close>×</button><div class="eyebrow">LEVEL ${state.level} · ${state.className.toUpperCase()}</div><h2>${state.name}</h2><p class="modal-lead">${state.faction} · A traveler of Haven's Rest</p><div class="stat-grid">${[['STR',s.str],['DEX',s.dex],['VIT',s.vit],['INT',s.int],['MAG',s.mag]].map(([k,v])=>`<div class="stat-box"><b>${v}</b><span>${k}</span></div>`).join('')}</div><div class="equip-grid"><div class="equip-row"><span>Health</span><b>${maxHp()}</b></div><div class="equip-row"><span>Mana</span><b>${maxMp()}</b></div><div class="equip-row"><span>Weapon power</span><b>${(classDefs[state.className].damage||0)+(weapon.damage||0)}</b></div><div class="equip-row"><span>Monsters defeated</span><b>${state.kills}</b></div></div><button class="secondary-btn" id="editFromSheet">EDIT CHARACTER</button>`);modal.querySelector('[data-close]').onclick=closeModal;modal.querySelector('#editFromSheet').onclick=()=>characterModal(false);}
function skillsModal(){const list=[['⚔','Melee','Physical strikes and weapon mastery.'],['⌁','Archery','Accuracy with ranged weapons.'],['✹','Magic','Spell power and mana control.'],['⛨','Defense','Resilience earned in battle.']];openModal(`<button class="modal-close" data-close>×</button><div class="eyebrow">PRACTICE MAKES MASTERY</div><h2>Skills & Spells</h2><p class="modal-lead">Skills improve as you use them. A true adventurer learns by doing.</p><div class="skills-list">${list.map(([icon,name,desc])=>`<div class="skill-row"><div class="skill-icon">${icon}</div><div><b>${name}</b><small>${desc}</small></div><em>${state.skills[name].toFixed(1)}</em></div>`).join('')}</div><label>KNOWN SPELLS</label><div class="skills-list"><div class="skill-row"><div class="skill-icon" style="color:#dc8963">✹</div><div><b>Ember bolt <small>12 mana · Target an enemy</small></b></div><em>KEY 1</em></div><div class="skill-row"><div class="skill-icon" style="color:#8fbd9a">✚</div><div><b>Mend <small>10 mana · Restore health</small></b></div><em>KEY 2</em></div></div>`);modal.querySelector('[data-close]').onclick=closeModal;}
function mapModal(){openModal(`<button class="modal-close" data-close>×</button><div class="eyebrow">ARESden · FRONTIER PROVINCE</div><h2>Atlas of Haven</h2><p class="modal-lead">A hand-drawn traveler's map. The meadow gate lies to the east.</p><div style="height:260px;position:relative;overflow:hidden;border:1px solid #6d6246;background:radial-gradient(ellipse at 50% 50%,#87966a,#607550 70%,#3e5742)"><div style="position:absolute;inset:10%;border:1px solid #d5c59666;transform:rotate(45deg);background:repeating-linear-gradient(45deg,transparent 0 34px,#d1bd8050 35px 36px)"></div><div style="position:absolute;left:45%;top:47%;color:#e2c57d;text-align:center;font:11px Cinzel,serif">✦<br>HAVEN</div><div style="position:absolute;right:7%;top:34%;color:#e4d4a9;font:italic 11px Cinzel,serif">WHISPERING<br>MEADOW</div><div style="position:absolute;right:10%;bottom:16%;color:#746e59;font-size:9px">OLD MINE</div><div style="position:absolute;left:51%;top:43%;width:7px;height:7px;border-radius:50%;background:#c75440;box-shadow:0 0 8px #f4c578"></div></div><div class="journal-list"><div class="journal-entry"><b>Haven's Rest</b><p>A quiet Aresden outpost. Captain Rowan watches the eastern road.</p></div><div class="journal-entry"><b>Whispering Meadow</b><p>Goblin scouts and hungry wolves stalk the old road beyond the gate.</p></div></div>`);modal.querySelector('[data-close]').onclick=closeModal;}
function journalModal(){openModal(`<button class="modal-close" data-close>×</button><div class="eyebrow">FIELD JOURNAL</div><h2>First Steps</h2><div class="journal-list"><div class="journal-entry"><b>${state.quest==='done'?'✓ ':''}A Favor for the Guard</b><p>Captain Rowan asked you to steady Haven's frontier. ${state.quest==='talk'?'Speak to him by the well to learn more.':state.quest==='hunt'?`Defeat goblin scouts in the meadow (${state.questKills}/3).`: 'Complete. The road is safer thanks to you.'}</p></div><div class="journal-entry"><b>Frontier Rumors</b><p>Merchants speak of old ruins past the meadow and strange lights under the hills.</p></div></div><button class="secondary-btn" data-close>RETURN TO THE REALM</button>`);modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);}
function dialogue(npc){if(npc.kind==='merchant'){openModal(`<button class="modal-close" data-close>×</button><div class="eyebrow">HAVEN'S REST · MERCHANT</div><h2>Mira the Trader</h2><p class="dialogue-text">"A tonic for the road, traveler? I buy goblin trinkets too. This frontier needs a little more trade and a lot less teeth."</p><div class="dialogue-options"><button id="buyTonic">Buy a health tonic · 8 crowns</button><button id="sellEar">Sell goblin ears · 5 crowns each</button><button data-close>Maybe later.</button></div>`);modal.querySelector('[data-close]').onclick=closeModal;modal.querySelector('#buyTonic').onclick=()=>{if(state.gold<8){toast('You do not have enough crowns.','bad');return;}state.gold-=8;state.potions++;updateHud();save();toast('Health tonic added to quick slot.','good');closeModal();};modal.querySelector('#sellEar').onclick=()=>{const i=state.inventory.indexOf('Goblin ear');if(i<0){toast('You have no goblin ears to trade.');return;}state.inventory.splice(i,1);state.gold+=5;updateHud();save();toast('Goblin ear sold for 5 crowns.','good');closeModal();};return;}
  if(npc.kind==='healer'){openModal(`<button class="modal-close" data-close>×</button><div class="eyebrow">HAVEN'S REST · SHRINE</div><h2>Sister Elowen</h2><p class="dialogue-text">"May the old lights keep you. Rest here, and let the wounds of the wilds fade."</p><div class="dialogue-options"><button id="blessBtn">Receive a blessing · 3 crowns</button><button data-close>Thank you, sister.</button></div>`);modal.querySelector('[data-close]').onclick=closeModal;modal.querySelector('#blessBtn').onclick=()=>{if(state.gold<3){toast('You need 3 crowns for a blessing.','bad');return;}state.gold-=3;state.hp=maxHp();state.mp=maxMp();updateHud();closeModal();toast('Restored to full health and mana.','good');};return;}
  const text=state.quest==='talk'?`"${state.name}, the meadow road is no longer safe. Goblin scouts have been sighted near the old stones. Will you help Haven?"`:state.quest==='hunt'&&state.questKills>=3?`"Well done, ${state.name}! The goblins have scattered. Take these crowns, and know that Haven remembers its friends."`:state.quest==='hunt'?`"The scouts still trouble us. Drive off three goblins, then come back to me. Watch for wolves on the road."`:`"The meadow is quiet again, thanks to you. Keep your blade sharp; the frontier is never still for long."`;
  openModal(`<button class="modal-close" data-close>×</button><div class="eyebrow">HAVEN'S REST · TOWN GUARD</div><h2>Captain Rowan</h2><p class="dialogue-text">${text}</p><div class="dialogue-options">${state.quest==='talk'?'<button id="acceptQuest">I will help Haven.</button>':''}${state.quest==='hunt'&&state.questKills>=3?'<button id="finishQuest">Claim the reward.</button>':''}<button data-close>I'll be on my way.</button></div>`);modal.querySelector('[data-close]').onclick=closeModal;if(modal.querySelector('#acceptQuest'))modal.querySelector('#acceptQuest').onclick=()=>{state.quest='hunt';closeModal();updateHud();save();toast('Quest started: The Meadow Watch.','good');};if(modal.querySelector('#finishQuest'))modal.querySelector('#finishQuest').onclick=()=>{state.quest='done';state.gold+=50;gainXp(75);state.inventory.push('Copper band');closeModal();updateHud();save();toast('Quest complete! +50 crowns · Copper band · 75 XP','good');};
}

function interact(npc){dialogue(npc);}
function save(){try{localStorage.setItem('emberfall-save',JSON.stringify({name:state.name,faction:state.faction,className:state.className,level:state.level,xp:state.xp,gold:state.gold,hp:state.hp,mp:state.mp,inventory:state.inventory,equipment:state.equipment,potions:state.potions,stats:state.stats,skills:state.skills,kills:state.kills,quest:state.quest,questKills:state.questKills,x:state.x,y:state.y}));}catch(_){}}
function load(){try{const d=JSON.parse(localStorage.getItem('emberfall-save'));if(!d)return false;Object.assign(state,d);state.selectedClass=state.className;state.selectedFaction=state.faction;state.hp=Math.min(state.hp,maxHp());state.mp=Math.min(state.mp,maxMp());return true;}catch(_){return false;}}
function getWorldAt(clientX,clientY){const r=canvas.getBoundingClientRect(),sx=clientX-r.left-r.width/2,sy=clientY-r.top-r.height/2;const dx=sx/TILE_W+sy/TILE_H,dy=sy/TILE_H-sx/TILE_W;return {x:Math.max(0,Math.min(WORLD-1,state.x+dx)),y:Math.max(0,Math.min(WORLD-1,state.y+dy))};}
function canvasClick(ev){const r=canvas.getBoundingClientRect(),mx=ev.clientX-r.left,my=ev.clientY-r.top;let nearest=null,dist=Infinity;const candidates=[...state.enemies.filter(e=>e.alive),...state.townNpc];for(const obj of candidates){const p=project(obj.x,obj.y),d=Math.hypot(p.x-mx,p.y-my);if(d<27&&d<dist){dist=d;nearest=obj;}}
  if(nearest){if(nearest.type){state.target=nearest;state.walkTo={x:nearest.x+(state.x<nearest.x?-1:1),y:nearest.y};updateHud();if(distance(state,nearest)<1.9)strike(nearest);else toast(`${nearest.type} targeted.`);}else{state.target=null;state.pendingNpc=nearest;state.walkTo={x:nearest.x+(state.x<nearest.x?-.9:.9),y:nearest.y};if(distance(state,nearest)<1.8){state.pendingNpc=null;interact(nearest);}}return;}
  const pos=getWorldAt(ev.clientX,ev.clientY);state.target=null;state.walkTo=pos;
}
canvas.addEventListener('click',canvasClick);
canvas.addEventListener('mousemove',ev=>{const r=canvas.getBoundingClientRect(),mx=ev.clientX-r.left,my=ev.clientY-r.top;let hit=false;for(const e of state.enemies.filter(x=>x.alive)){const p=project(e.x,e.y);if(Math.hypot(p.x-mx,p.y-my)<25){hit=true;break;}}for(const n of state.townNpc){const p=project(n.x,n.y);if(Math.hypot(p.x-mx,p.y-my)<24)hit=true;}canvas.style.cursor=hit?'pointer':'crosshair';});
const keys=new Set();window.addEventListener('keydown',ev=>{const key=ev.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))ev.preventDefault();if(!keys.has(key)&&!state.modal){if(key===' '||key==='q')strike();if(key==='1')castSpell('fire');if(key==='2')castSpell('heal');if(key==='3')usePotion();if(key==='i')equipmentModal();if(key==='c')characterSheet();if(key==='k')skillsModal();if(key==='m')mapModal();if(key==='e'){const npc=state.townNpc.slice().sort((a,b)=>distance(state,a)-distance(state,b))[0];if(npc&&distance(state,npc)<2.7)interact(npc);else toast('No one nearby to speak with.');}if(key==='escape'&&state.modal)closeModal();}keys.add(key);});window.addEventListener('keyup',ev=>keys.delete(ev.key.toLowerCase()));
const baseUpdate=update; // Keep keyboard movement responsive alongside click-to-move.
function frameUpdate(dt){baseUpdate(dt);let dx=0,dy=0;if(keys.has('w')||keys.has('arrowup')){dx--;dy--;}if(keys.has('s')||keys.has('arrowdown')){dx++;dy++;}if(keys.has('a')||keys.has('arrowleft')){dx--;dy++;}if(keys.has('d')||keys.has('arrowright')){dx++;dy--;}if(dx||dy){const n=Math.hypot(dx,dy);state.x=Math.max(1,Math.min(WORLD-1,state.x+dx/n*dt*4));state.y=Math.max(1,Math.min(WORLD-1,state.y+dy/n*dt*4));state.walkTo=null;}}
// Replace the animation callback's update path with keyboard-aware movement.
const oldLoop=loop;
// A tiny independent driver keeps HUD updates and world animation in lockstep.
let frameLast=performance.now();
function gameFrame(now){const dt=Math.min(.05,(now-frameLast)/1000);frameLast=now;frameUpdate(dt);render();requestAnimationFrame(gameFrame);}
// Cancel the initial loop before starting the keyboard-aware loop.
// requestAnimationFrame's first loop is replaced by using a single frame token.

