115:   function gainXp(amount){state.xp+=amount;while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.stats.vit++;state.stats.str++;state.hp=maxHp();state.mp=maxMp();say(`Level ${state.level} reached! Your strength grows.`,'good');}updateHud();save();}
116:   function addItem(item){state.inventory.push(item);if(item==='Minor health tonic')state.potions++;say(`${item} added to your bag.`,'good');updateHud();save();}
117:   function attack(spell=false){
118:     const e=state.target?.alive?state.target:state.enemies.filter(v=>v.alive&&dist(v,state)<3).sort((a,b)=>dist(a,state)-dist(b,state))[0];
119:     if(!e){say('No foe is close enough.');return;}state.target=e;
120:     if(spell){if(state.mp<12){say('Not enough mana.');return;}state.mp-=12;}
121:     const base=CLASSES[state.className].power+(ITEMS[state.equipment.weapon]?.power||0)+(spell?state.stats.mag*1.7:state.stats.str*.55);
122:     const damage=Math.round(base*(.8+Math.random()*.45));e.hp-=damage;e.aggro=true;floatText(e.x,e.y,`-${damage}`,spell?'#a9d8e6':'#f1d38c');state.attackCooldown=.36;
123:     if(e.hp<=0){e.alive=false;e.respawn=18;state.kills++;state.gold+=5+Math.floor(Math.random()*8);say(`${e.type} defeated · +${e.type==='Meadow Wolf'?35:25} XP`,'good');gainXp(e.type==='Meadow Wolf'?35:25);
124:       if(e.type==='Goblin Scout'&&state.quest==='hunt'){state.questKills=Math.min(3,state.questKills+1);if(state.questKills>=3)say('The meadow is safer. Return to Captain Rowan.','good');}
125:       if(Math.random()<.3)addItem(Math.random()<.18?'Copper ring':'Minor health tonic');if(Math.random()<.04)addItem('Moonstone charm');state.target=null;
126:     }updateHud();
127:   }
128:   function usePotion(){if(state.potions<1){say('You have no health tonics.');return;}if(state.hp>=maxHp()){say('Your health is already full.');return;}state.potions--;state.hp=Math.min(maxHp(),state.hp+48);floatText(state.x,state.y,'+48','#a7d27b');say('You drink a minor health tonic.','good');updateHud();save();}
129:   function castHeal(){if(state.mp<16){say('Not enough mana.');return;}state.mp-=16;state.hp=Math.min(maxHp(),state.hp+35);floatText(state.x,state.y,'+35','#9ce0a2');say('Mend restores your vitality.','good');updateHud();}
130:   function nearestNpc(){return NPCS.filter(n=>dist(n,state)<2.4).sort((a,b)=>dist(a,state)-dist(b,state))[0];}
