135:       else if(state.quest==='hunt'&&state.questKills>=3){state.quest='done';state.gold+=75;addItem('Mossy cap');gainXp(80);openDialog('Captain Rowan','Fine work. The eastern road is safe again. Take these crowns and this cap as a token of Haven’s gratitude.',[['Thank you','closeDialog']]);}
136:       else openDialog('Captain Rowan',state.quest==='hunt'?`The meadow still needs your help. Goblins defeated: ${state.questKills}/3.`:'The folk of Haven remember your courage. Keep your blade ready.',[['Understood','closeDialog']]);
137:     }else if(npc.kind==='merchant')openDialog('Mira the Trader','A fair price for a fair traveler. Choose what you need.',[['Health tonic · 18 crowns',()=>buyItem('Minor health tonic',18)],['Copper ring · 35 crowns',()=>buyItem('Copper ring',35)],['Short bow · 45 crowns',()=>buyItem('Short bow',45)],['Leave','closeDialog']]);
