const { chromium } = require('playwright');
(async() => {
  const browser = await chromium.launch({headless:true,args:['--no-sandbox']});
  const page = await browser.newPage({viewport:{width:1440,height:1000}});
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', msg => { if (msg.type() === 'error') errors.push('CONSOLE: ' + msg.text()); });
  await page.goto('http://localhost:3002/', {waitUntil:'load'});
  await page.waitForTimeout(1200);

  // Move around and interact with guard
  const canvas = page.locator('#world');
  await page.keyboard.down('w');
  await page.waitForTimeout(1200);
  await page.keyboard.up('w');
  await page.keyboard.press('e');
  await page.waitForTimeout(500);
  let dialogText = await page.locator('#modal').innerText();
  console.log('DIALOG_AFTER_E: ' + dialogText.slice(0,150).replace(/\n/g,' | '));

  // Accept quest if present
  const accept = page.locator('button', { hasText: 'Accept the task' });
  if (await accept.count()) { await accept.first().click(); }
  await page.waitForTimeout(300);

  // Open bag and test use of tonic
  await page.keyboard.press('i');
  await page.waitForTimeout(300);
  const bagText = await page.locator('#modal').innerText();
  console.log('BAG_TEXT_HAS_TONIC: ' + /Minor health tonic/i.test(bagText));

  // Try keys for quick actions
  await page.keyboard.press('3');
  await page.waitForTimeout(200);
  const hpText = await page.locator('#hpText').innerText();
  console.log('HP_TEXT_AFTER_TONIC: ' + hpText);

  // Close modal if open
  await page.keyboard.press('Escape');
  await page.waitForTimeout(200);

  console.log('ERRORS:', errors.length ? errors : 'NONE');
  await browser.close();
})();
NODE
